function evidence = f90_xbatt05_extract_candidate_evidence( ...
        candidatePath, outDir)
%F90_XBATT05_EXTRACT_CANDIDATE_EVIDENCE Candidate charge-sequence replay.
arguments
    candidatePath (1,1) string
    outDir (1,1) string
end
[taskRoot,sharedRoot]=localRoots("F90-XBATT-05");
addpath(sharedRoot,"-begin");cleanup=onCleanup(@()rmpath(sharedRoot)); %#ok<NASGU>
official=jsondecode(fileread(simuverity_official_scenarios_path()));
spec=struct("schema","simuverity.f90-xbatt05-evidence.v1", ...
    "task_id","F90-XBATT-05","scenarios",official.scenarios, ...
    "output_contract",localOutputs,"input_builder",@localInputs, ...
    "requested_input_builder",@localRequested, ...
    "stop_time",@(~,~)double(official.simulation.stop_time_s), ...
    "postprocess",@localPostprocess,"static_audit",@localAudit, ...
    "evidence_sample_s",double(official.simulation.stop_time_s)/4999);
evidence=simuverity_run_candidate_evidence(candidatePath,outDir,spec);
end
function rows=localOutputs
rows=localRows(["cell_state","charger_state","electrochemical_state"],[4 4 8]);
rows(2).interpolation="previous";
rows(2).event_columns=1;
end
function inputs=localInputs(s,~)
inputs=rmfield(s,intersect(fieldnames(s),{'id','class'}));
end
function requested=localRequested(s,~),requested=localInputs(s,struct);end
function row=localPostprocess(row,outputs,~,~)
t=double(outputs.time_s(:));cellState=double(outputs.cell_state);
charger=double(outputs.charger_state);electro=double(outputs.electrochemical_state);
phase=charger(:,1);command=charger(:,2);voltage=cellState(:,1);
current=cellState(:,2);temperature=cellState(:,3);soc=cellState(:,4);
cpStart=localFirstTime(t,phase==1,-inf);
restAfter=localFirstTime(t,phase==0,cpStart+100);
ccStart=localFirstTime(t,phase==2,restAfter+100);
cvStart=localFirstTime(t,phase==3,ccStart+100);
finalRest=localFirstTime(t,phase==0,cvStart+100);
sequence=all(isfinite([cpStart,restAfter,ccStart,cvStart,finalRest]))&& ...
    cpStart<restAfter&&restAfter<ccStart&&ccStart<cvStart&&cvStart<finalRest;
cp=phase==1&t>=cpStart&t<restAfter;cc=phase==2&t>=ccStart&t<cvStart;
cv=phase==3&t>=cvStart&t<finalRest;indices=find(cv);
if isempty(indices),cvInitial=nan;cvFinal=nan;else
head=indices(1:min(10,numel(indices)));tail=indices(max(1,end-9):end);
cvInitial=median(abs(current(head)));cvFinal=median(abs(current(tail)));end
row.metrics=struct("full_sequence_pass",sequence,"cp_start_s",cpStart, ...
    "rest_after_cp_s",restAfter,"cc_start_s",ccStart,"cv_start_s",cvStart, ...
    "final_rest_start_s",finalRest,"cp_power_median_W",localMedian(charger(cp,3)), ...
    "cp_power_relative_error",abs(localMedian(charger(cp,3))+5)/5, ...
    "cc_current_median_A",localMedian(current(cc)), ...
    "cc_current_relative_error",abs(localMedian(current(cc))-5)/5, ...
    "cv_voltage_median_V",localMedian(voltage(cv)), ...
    "cv_voltage_absolute_error_V",abs(localMedian(voltage(cv))-4.2), ...
    "cv_initial_current_A",cvInitial,"cv_final_current_A",cvFinal, ...
    "cv_taper_ratio",cvFinal/max(cvInitial,eps),"voltage_min_V",min(voltage), ...
    "voltage_max_V",max(voltage),"temperature_min_C",min(temperature), ...
    "temperature_max_C",max(temperature),"soc_min",min(soc),"soc_max",max(soc), ...
    "completed_sequence_count",max(charger(:,4)), ...
    "film_growth_um",electro(end,4)-electro(1,4), ...
    "porosity_change",electro(end,5)-electro(1,5), ...
    "capacity_soh_change",electro(end,6)-electro(1,6), ...
    "sei_capacity_loss_change",electro(end,7)-electro(1,7), ...
    "plating_capacity_loss_change",electro(end,8)-electro(1,8), ...
    "command_values",unique(command).');
row.outputs=outputs;row.valid=row.output_contract.all_required_pass&&sequence;
end
function value=localFirstTime(t,mask,threshold)
i=find(mask&t>threshold+1e-9,1);if isempty(i),value=nan;else,value=t(i);end
end
function value=localMedian(x),if isempty(x),value=nan;else,value=median(x);end,end
function audit=localAudit(model,spec)
structure=simuverity_candidate_structure(model,string({spec.output_contract.name})');
semantic=structure.semantic_types;
cellCount=nnz(contains(semantic,["battery","electrochemical","cell"]));
source=nnz(contains(semantic,["controlled current","controlled voltage", ...
    "controlled source"]));voltageSensor=nnz(contains(semantic,"voltage sensor"));
currentSensor=nnz(contains(semantic,"current sensor"));
thermal=nnz(contains(semantic,["convective","temperature source","thermal"]));
stateflow=nnz(contains(semantic,"stateflow"));feedback=structure.signal_cycle_present;
audit=struct("cell_component_path",localChoice(cellCount>=1, ...
    "candidate_physical_cell","missing"), ...
    "charger_is_stateflow",stateflow>=1,"charger_input_port_count",source, ...
    "convective_heat_transfer_present",thermal>=1, ...
    "temperature_source_present",thermal>=1, ...
    "physical_voltage_sensor_present",voltageSensor>=1, ...
    "physical_current_sensor_present",currentSensor>=1, ...
    "measurement_feedback_connected",feedback, ...
    "command_actuator_connected",feedback&&source>=1, ...
    "dynamic_state_block_count",structure.dynamic_block_count, ...
    "connected_public_output_count",structure.connected_output_count, ...
    "nontrivial_public_output_source_count", ...
        structure.nontrivial_output_source_count, ...
    "feedback_cycle_present",feedback, ...
    "core_path_qualified", ...
        structure.connected_output_count==numel(spec.output_contract) && ...
        structure.nontrivial_output_source_count==numel(spec.output_contract) && ...
        structure.dynamic_block_count>=1);
end
function value=localChoice(test,a,b),if test,value=a;else,value=b;end,end
function rows=localRows(names,widths)
rows=repmat(struct("name","","evidence_name","","width",0, ...
    "interpolation","linear","event_columns",[]),numel(names),1);
for k=1:numel(names),rows(k).name=names(k);rows(k).evidence_name=names(k); ...
    rows(k).width=widths(k);end
end
function [taskRoot,sharedRoot]=localRoots(taskId)
scriptRoot=fileparts(mfilename("fullpath"));tasksRoot=fileparts(scriptRoot);
sharedRoot=fullfile(tasksRoot,"_shared");repoRoot=tasksRoot;
for k=1:3,repoRoot=fileparts(repoRoot);end
taskRoot=string(getenv("SIMUVERITY_TASK_ROOT"));
end
